    else
      url "https://github.com/crueber/coldstorage/releases/download/v#{version}/coldstorage_#{version}_macOS_x86_64.tar.gz"
      sha256 "b16a951bf000d97cb0853b6e8362136d26a357a73212f09259d1466b5984c6a1"
    end
  end

  on_linux do
    if Hardware::CPU.arm?
